func (v *NullableKeyInstance) Unset() {
	v.value = nil
	v.isSet = false
}

func NewNullableKeyInstance(val *KeyInstance) *NullableKeyInstance {
	return &NullableKeyInstance{value: val, isSet: true}
}

func (v NullableKeyInstance) MarshalJSON() ([]byte, error) {
	return json.Marshal(v.value)
}

func (v *NullableKeyInstance) UnmarshalJSON(src []byte) error {
	v.isSet = true
	return json.Unmarshal(src, &v.value)
}
